<?php
declare(strict_types=1);
$statusLabels = ['draft' => 'Drafts', 'posted' => 'Posted', 'reversed' => 'Reversed', 'all' => 'All transactions'];
$selectedStatus = $filters['status'];
$scopeQuery = $filters;
?>
<div class="review-console <?= $detailOnly ? 'detail-only' : '' ?>">
<section class="transaction-list" aria-label="Transaction list">
    <div class="list-heading"><div><p class="eyebrow">Your day-to-day books</p><h1><?= pl_e($statusLabels[$selectedStatus] ?? 'Transactions') ?></h1><p class="muted"><?= (int) $list['total'] ?> <?= $list['total'] === 1 ? 'record' : 'records' ?> · <?= pl_e($company['currency']) ?></p></div>
        <?php if (pl_can_write($company)): ?><a class="button primary" href="<?= pl_e(pl_url('/transactions/new')) ?>"><?= pl_icon('plus') ?> New transaction</a><?php endif; ?></div>
    <nav class="status-tabs" aria-label="Transaction status"><?php foreach ($statusLabels as $key => $label): ?><a href="<?= pl_e(pl_url('/transactions', array_replace($scopeQuery, ['status' => $key, 'page' => 1]))) ?>" <?= $selectedStatus === $key ? 'aria-current="page"' : '' ?>><?= pl_e($label) ?></a><?php endforeach; ?></nav>
    <form class="list-filters" action="<?= pl_e(pl_url('/transactions')) ?>" method="get">
        <input type="hidden" name="status" value="<?= pl_e($selectedStatus) ?>">
        <label class="search-field"><span class="sr-only">Search transactions</span><?= pl_icon('search') ?><input type="search" name="search" value="<?= pl_e($filters['search']) ?>" placeholder="Name, reference or memo"></label>
        <label><span class="sr-only">Transaction type</span><select name="kind"><option value="all">All types</option><option value="expense" <?= $filters['kind'] === 'expense' ? 'selected' : '' ?>>Expenses</option><option value="receipt" <?= $filters['kind'] === 'receipt' ? 'selected' : '' ?>>Receipts</option></select></label>
        <button class="button secondary" type="submit">Filter</button>
        <details class="date-filters"><summary>Date range</summary><div><label>From <input type="date" name="from" value="<?= pl_e($filters['from']) ?>"></label><label>To <input type="date" name="to" value="<?= pl_e($filters['to']) ?>"></label><button class="button secondary" type="submit">Apply dates</button></div></details>
        <?php if ($filters['search'] || $filters['from'] || $filters['to'] || $filters['kind'] !== 'all'): ?><a class="clear-filter" href="<?= pl_e(pl_url('/transactions', ['status' => $selectedStatus])) ?>">Clear filters</a><?php endif; ?>
    </form>
    <div class="transaction-table table-wrap"><table class="data-table">
        <caption class="sr-only">Choose a transaction to inspect its details</caption>
        <thead><tr><th scope="col">Date / reference</th><th scope="col">Name</th><th scope="col" class="amount">Amount</th><th scope="col">Status</th></tr></thead>
        <tbody><?php foreach ($list['documents'] as $row): $selected = $document && (int) $document['id'] === (int) $row['id']; ?>
        <tr class="<?= $selected ? 'selected' : '' ?>"><td><a class="record-link" href="<?= pl_e(pl_url('/transactions/detail', array_replace($scopeQuery, ['id' => $row['id']]))) ?>" <?= $selected ? 'aria-current="true"' : '' ?> data-record-link><strong><?= pl_e(pl_date_label($row['date'])) ?></strong><span class="muted"><?= pl_e($row['number']) ?></span></a></td><td><span class="payee"><?= pl_e($row['counterparty'] ?: 'No name entered') ?></span><span class="muted row-secondary"><?= pl_e(ucfirst($row['kind'])) ?></span></td><td class="amount"><?= pl_e(pl_money($row['amount'])) ?></td><td><span class="badge <?= pl_e($row['status']) ?>"><?= pl_e(ucfirst($row['status'])) ?></span></td></tr>
        <?php endforeach; ?></tbody>
    </table>
    <?php if (!$list['documents']): ?><div class="empty-state"><?= pl_icon('receipt') ?><h2><?= $selectedStatus === 'draft' ? 'A clear place to start.' : 'No matching transactions.' ?></h2><p><?= $selectedStatus === 'draft' ? 'Record money in or money out. Review the balanced entry before it reaches your books.' : 'Try another status or adjust your filters.' ?></p><?php if (pl_can_write($company)): ?><a href="<?= pl_e(pl_url('/transactions/new')) ?>" class="button primary">Record your first transaction</a><?php endif; ?></div><?php endif; ?>
    </div>
    <div class="list-footer"><span><?= (int) $list['total'] ?> records · Total <strong><?= pl_e($company['currency'] . ' ' . pl_money($list['total_amount'])) ?></strong></span><div class="pagination"><?php if ($list['page'] > 1): ?><a class="icon-button" aria-label="Previous page" href="<?= pl_e(pl_url('/transactions', array_replace($scopeQuery, ['page' => $list['page'] - 1]))) ?>"><?= pl_icon('chevron-left') ?></a><?php endif; ?><span>Page <?= (int) $list['page'] ?> of <?= max(1, (int) $list['pages']) ?></span><?php if ($list['page'] < $list['pages']): ?><a class="icon-button" aria-label="Next page" href="<?= pl_e(pl_url('/transactions', array_replace($scopeQuery, ['page' => $list['page'] + 1]))) ?>"><?= pl_icon('chevron-right') ?></a><?php endif; ?></div></div>
    <?php if ($company['is_sample']): ?><p class="sample-note"><?= pl_icon('info-circle') ?> These are synthetic records in a separate sample company.</p><?php endif; ?>
</section>
<section class="transaction-detail" aria-label="Transaction details">
<?php if ($document): ?>
    <a class="back-to-list" href="<?= pl_e(pl_url('/transactions', $scopeQuery)) ?>"><?= pl_icon('arrow-left') ?> Back to list</a>
    <?php if ($form['message']): ?><div class="alert" role="alert"><strong>We couldn't complete that action.</strong><p><?= pl_e($form['message']) ?></p></div><?php endif; ?>
    <div class="detail-heading"><div><div class="inline-heading"><h2><?= pl_e($document['number']) ?></h2><span class="badge <?= pl_e($document['status']) ?>"><?= pl_e(ucfirst($document['status'])) ?></span></div><h3><?= pl_e($document['counterparty'] ?: ucfirst($document['kind'])) ?></h3></div><p class="detail-amount"><?= pl_e($company['currency']) ?> <strong><?= pl_e(pl_money($document['amount'])) ?></strong></p></div>
    <div class="detail-tabs" aria-label="Record sections"><a href="#record-details">Details</a><a href="#record-journal">Journal</a><a href="#record-history">History</a></div>
    <dl class="record-details" id="record-details"><div><dt><?= $document['kind'] === 'expense' ? 'Paid to' : 'Received from' ?></dt><dd><?= pl_e($document['counterparty'] ?: '—') ?></dd></div><div><dt>Reference</dt><dd><?= pl_e($document['reference'] ?: '—') ?></dd></div><div><dt>Date</dt><dd><?= pl_e(pl_date_label($document['date'])) ?></dd></div><div><dt><?= $document['kind'] === 'expense' ? 'Paid from' : 'Received into' ?></dt><dd><?= pl_e($document['money_account_name']) ?></dd></div><div><dt>Category</dt><dd><?= pl_e($document['category_account_name']) ?></dd></div><div><dt>Memo</dt><dd><?= pl_e($document['memo'] ?: '—') ?></dd></div></dl>
    <section id="record-journal" class="journal-section"><div class="section-heading"><h3><?= $document['status'] === 'draft' ? 'Posting preview' : 'Posted journal' ?></h3><span class="balanced-label"><?= pl_icon('check') ?> Balanced</span></div>
        <?php $entryLines = $document['journal'] ? $document['journal']['lines'] : $document['journal_preview']['lines']; require __DIR__ . '/../partials/entry.php'; ?>
        <p class="muted small"><?= $document['status'] === 'draft' ? 'Posting adds this transaction to reports. A saved draft does not change your books.' : 'This entry is included in your reports. Posted financial details are preserved.' ?> <?php if ($document['journal_id']): ?><a href="<?= pl_e(pl_url('/journals/detail', ['id' => $document['journal_id']])) ?>">Open journal <?= pl_e($document['journal']['reference']) ?></a><?php endif; ?></p>
    </section>
    <details id="record-history" class="history-section"><summary>History <span class="muted">· Revision <?= (int) $document['revision'] ?></span></summary><dl class="record-details"><div><dt>Created</dt><dd><time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $document['created_at']) . 'Z') ?>"><?= pl_e($document['created_at']) ?> UTC</time></dd></div><div><dt>Last saved</dt><dd><time data-local-time datetime="<?= pl_e(str_replace(' ', 'T', $document['updated_at']) . 'Z') ?>"><?= pl_e($document['updated_at']) ?> UTC</time></dd></div></dl><?php if ($document['reversal_journal_id']): ?><p><a href="<?= pl_e(pl_url('/journals/detail', ['id' => $document['reversal_journal_id']])) ?>">Inspect the linked reversal</a></p><?php endif; ?></details>
    <?php if (pl_can_write($company)): ?><div class="detail-actions">
        <?php if ($document['status'] === 'draft'): ?><a class="button secondary" href="<?= pl_e(pl_url('/transactions/edit', ['id' => $document['id']])) ?>">Edit draft</a><form method="post" action="<?= pl_e(pl_url('/transactions/post')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="id" value="<?= (int) $document['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $document['revision'] ?>"><button class="button primary" type="submit" <?= $company['setup_status'] !== 'ready' ? 'disabled' : '' ?>>Post <?= pl_e($document['kind']) ?></button></form>
        <?php elseif ($document['status'] === 'posted'): ?><a class="button secondary" href="<?= pl_e(pl_url('/reports/trial-balance')) ?>">See report effect</a><a class="text-button" href="#reverse-entry" data-open-details>Reverse transaction</a>
        <?php else: ?><a class="button secondary" href="<?= pl_e(pl_url('/reports/trial-balance')) ?>">View trial balance</a><span class="muted">Original and reversal retained</span><?php endif; ?>
    </div><?php endif; ?>
    <?php if ($document['status'] === 'posted' && pl_can_write($company)): ?><details class="reversal-form" id="reverse-entry" <?= $form['message'] ? 'open' : '' ?>><summary>Correct this entry with a reversal</summary><p>A reversal creates an opposite, linked entry on the date you choose. It preserves this transaction.</p><form method="post" action="<?= pl_e(pl_url('/transactions/reverse')) ?>"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><input type="hidden" name="id" value="<?= (int) $document['id'] ?>"><div class="form-grid"><label class="field">Reversal date<input type="date" name="date" value="<?= pl_e(pl_web_text($form['input'], 'date', gmdate('Y-m-d'))) ?>" required <?= !isset($form['input']['date']) ? 'data-local-today' : '' ?>></label><label class="field full-width">Reason<textarea name="reason" rows="2" maxlength="500" required><?= pl_e(pl_web_text($form['input'], 'reason')) ?></textarea></label></div><button type="submit" class="button secondary">Post linked reversal</button></form></details><?php endif; ?>
<?php else: ?><div class="empty-detail"><span class="detail-mark"><?= pl_icon('book') ?></span><h2>Every entry tells a story.</h2><p>Select a transaction to see where the money went and how it appears in your books.</p></div><?php endif; ?>
</section>
</div>
